package monstraria.view;

import javax.imageio.ImageIO;
import javax.swing.*;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.util.Base64;

/**
 * Pano de fundo do menu inicial: cena de ruínas na selva (imagem de referência
 * fornecida pelo usuário), desenhada em modo "cover" (preenche todo o painel,
 * cortando o excedente) com um leve véu escuro para dar contraste ao conteúdo
 * do menu (título e botões) que fica sobreposto.
 */
class FundoFloresta extends JPanel {

    private BufferedImage cache;
    private int cacheW = -1, cacheH = -1;
    private static BufferedImage imagemFundo;
    private static boolean imagemCarregada = false;

    FundoFloresta() {
        setOpaque(true);
    }

    @Override
    protected void paintComponent(Graphics graphics) {
        super.paintComponent(graphics);
        int w = getWidth(), h = getHeight();
        if (w <= 0 || h <= 0) return;
        if (cache == null || cacheW != w || cacheH != h) {
            cacheW = w;
            cacheH = h;
            cache = renderizarCena(w, h);
        }
        graphics.drawImage(cache, 0, 0, null);
    }

    /** Desenha a foto de fundo em modo "cover" (preenche e corta o excedente) e aplica um véu escuro. */
    private static BufferedImage renderizarCena(int w, int h) {
        BufferedImage saida = new BufferedImage(w, h, BufferedImage.TYPE_INT_RGB);
        Graphics2D g = saida.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        g.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);

        BufferedImage foto = obterImagemFundo();
        if (foto != null) {
            int fw = foto.getWidth(), fh = foto.getHeight();
            double escala = Math.max((double) w / fw, (double) h / fh);
            int dw = (int) Math.ceil(fw * escala);
            int dh = (int) Math.ceil(fh * escala);
            int dx = (w - dw) / 2;
            int dy = (h - dh) / 2;
            g.drawImage(foto, dx, dy, dw, dh, null);
        } else {
            // reserva: fundo esverdeado sólido caso a imagem não possa ser decodificada
            g.setColor(new Color(14, 24, 18));
            g.fillRect(0, 0, w, h);
        }

        // véu escuro sutil para dar contraste ao título e aos botões do menu
        g.setColor(new Color(5, 10, 8, 115));
        g.fillRect(0, 0, w, h);

        // leve vinheta nas bordas superior e inferior
        g.setColor(new Color(0, 0, 0, 90));
        g.fillRect(0, 0, w, Math.max(1, (int) (h * 0.06)));
        g.fillRect(0, (int) (h * 0.94), w, Math.max(1, h - (int) (h * 0.94)));

        g.dispose();
        return saida;
    }

    /** Decodifica a imagem embutida (base64) uma única vez e reaproveita entre todas as instâncias. */
    private static synchronized BufferedImage obterImagemFundo() {
        if (!imagemCarregada) {
            imagemCarregada = true;
            try {
                byte[] dados = Base64.getDecoder().decode(IMG_RUINAS_SELVA_B64);
                imagemFundo = ImageIO.read(new ByteArrayInputStream(dados));
            } catch (IOException | IllegalArgumentException ex) {
                imagemFundo = null;
            }
        }
        return imagemFundo;
    }

    // Imagem de referência (ruínas na selva) embutida em base64 para manter o
    // projeto autocontido (sem depender de arquivos externos no classpath).
    private static final String IMG_RUINAS_SELVA_B64 =
            "" +
            "";
}
